//! Swift: the `Azul` module (`target/codegen/azul.swift`, generated by
//! `doc/src/codegen/v2/lang_swift`).
//!
//! Spellings: native Swift enums with lowerCamel cases (`LayoutDisplay.flex`,
//! `LayoutWidth.px(..)`, `LayoutWidthValue.exact(..)`, `CssProperty.whiteSpace(..)`
//! for the variant, the static func `CssProperty.width(_: LayoutWidth)` for
//! the api.json constructor), structs with labelled initialisers
//! (`ColorU(r: 255, g: 0, b: 0, a: 255)`, `StyleTextColor(inner: ..)`),
//! api `create` constructors as `init(_:)` (`FloatValue(1.0)`), first
//! argument unlabelled and the rest labelled (`PixelValue.fromMetric(.., value:)`),
//! native `String`s, and native arrays wherever a Vec is expected.

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{EnumShape, Item, Module, Prim},
    lang::{
        call_param_names, escape_quoted, is_droppable_vec, item_comments, item_doc,
        unicode_braced, ExprSyntax,
    },
    CodegenBackend, GeneratedFile,
};

/// The Swift printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Swift;

/// `lower_leading` + `camel` of `doc/src/codegen/v2/lang_swift/mod.rs`:
/// `text_color` -> `textColor`, `MacOS` -> `macOS`, `IOS` -> `ios`,
/// `W500` -> `w500`.
#[must_use]
pub fn swift_camel(name: &str) -> String {
    let mut out = String::new();
    for (i, part) in name.split('_').filter(|p| !p.is_empty()).enumerate() {
        if i == 0 {
            let chars: Vec<char> = part.chars().collect();
            let run = chars.iter().take_while(|c| c.is_ascii_uppercase()).count();
            let lower_to = if run <= 1 || run == chars.len() {
                run
            } else if chars[run].is_ascii_lowercase() {
                run - 1
            } else {
                run
            };
            out.extend(chars.iter().enumerate().map(|(j, c)| {
                if j < lower_to {
                    c.to_ascii_lowercase()
                } else {
                    *c
                }
            }));
        } else {
            out.push_str(&crate::codegen::ir::capitalize(part));
        }
    }
    out
}

/// `reserved_member` of the Swift generator: these get a trailing `_`.
const RESERVED_MEMBERS: &[&str] = &[
    "description", "debugDescription", "hashValue", "hash", "copy", "init", "deinit", "self",
    "Type", "Protocol", "default", "downcast", "subscript",
];

/// Swift keywords, wrapped in backticks when used as a name.
const KEYWORDS: &[&str] = &[
    "associatedtype", "class", "deinit", "enum", "extension", "fileprivate", "func", "import",
    "init", "inout", "internal", "let", "open", "operator", "private", "precedencegroup",
    "protocol", "public", "rethrows", "static", "struct", "subscript", "typealias", "var",
    "break", "case", "catch", "continue", "default", "defer", "do", "else", "fallthrough", "for",
    "guard", "if", "in", "repeat", "return", "switch", "where", "while", "as", "Any", "false",
    "is", "true", "nil", "self", "super", "throw", "throws", "try",
];

/// A member / case name as the Swift generator spells it.
fn member(name: &str) -> String {
    let mut n = swift_camel(name);
    if RESERVED_MEMBERS.contains(&n.as_str()) {
        n.push('_');
    }
    if KEYWORDS.contains(&n.as_str()) {
        format!("`{n}`")
    } else {
        n
    }
}

impl ExprSyntax for Swift {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, ty: Prim) -> String {
        let t = if ty == Prim::F64 { "Double" } else { "Float" };
        match text {
            "nan" => format!("{t}.nan"),
            "inf" => format!("{t}.infinity"),
            "-inf" => format!("-{t}.infinity"),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("\"{}\"", escape_quoted(s, &[], &unicode_braced)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, broken: bool) -> Doc {
        let names = call_param_names(class, method);
        let args = args
            .into_iter()
            .enumerate()
            .map(|(i, a)| match names.get(i) {
                Some(n) if i > 0 => Doc::cat(vec![Doc::text(format!("{}: ", swift_camel(n))), a]),
                _ => a,
            })
            .collect();
        if method == "create" {
            Doc::call(class.to_string(), args, broken)
        } else {
            Doc::call(format!("{class}.{}", member(method)), args, broken)
        }
    }

    fn variant(&self, ty: &str, _shape: EnumShape, variant: &str, args: Vec<Doc>, broken: bool) -> Doc {
        let case = format!("{ty}.{}", member(variant));
        if args.is_empty() {
            Doc::text(case)
        } else {
            Doc::call(case, args, broken)
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, broken: bool) -> Doc {
        let fields = fields
            .into_iter()
            .map(|(k, v)| {
                let mut label = swift_camel(&k);
                if RESERVED_MEMBERS.contains(&label.as_str()) {
                    label.push('_');
                }
                Doc::cat(vec![Doc::text(format!("{label}: ")), v])
            })
            .collect();
        Doc::call(ty.to_string(), fields, broken)
    }

    fn vec(&self, _ty: &str, _elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        Doc::list("[", items, ", ", "]", false, broken, true)
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("fatalError({:?})", format!("not expressible: {what}")))
    }
}

fn item_fn(item: &Item) -> String {
    let mut out = String::new();
    for line in &item_comments(&Swift, item) {
        out.push_str(&format!("// {line}\n"));
    }
    let name = item.name.lower_camel();
    let ty = if is_droppable_vec(&item.ty) {
        "[CssPropertyWithConditions]".to_string()
    } else {
        item.ty.clone()
    };
    match item_doc(&Swift, item) {
        Ok(doc) => out.push_str(&format!(
            "public func {name}() -> {ty} {{\n    return {}\n}}\n",
            render(&doc, "    ", 1)
        )),
        Err(reason) => out.push_str(&format!(
            "// not expressible with the Swift bindings: {reason}\npublic func {name}() -> {ty}? \
             {{\n    return nil\n}}\n"
        )),
    }
    out
}

impl CodegenBackend for Swift {
    fn lang(&self) -> &'static str {
        "swift"
    }

    fn display_name(&self) -> &'static str {
        "Swift"
    }

    fn extension(&self) -> &'static str {
        "swift"
    }

    fn emit_module(&self, m: &Module) -> String {
        let mut out =
            String::from("// Generated by azul-css codegen (Swift). Do not edit by hand.\nimport Azul\n");
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_fn(item));
        }
        out
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        let mut main = String::new();
        for item in &m.items {
            let name = item.name.lower_camel();
            main.push_str(&format!(
                "let {name}Value = {name}()\nprint(\"{name}: \\({name}Value.count) properties\")\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "Package.swift".to_string(),
                contents: PACKAGE.to_string(),
            },
            GeneratedFile {
                path: "Sources/AzulStyles/Styles.swift".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "Sources/AzulStyles/main.swift".to_string(),
                contents: main,
            },
        ]
    }
}

const PACKAGE: &str = r#"// swift-tools-version:5.7
// Copy target/codegen/swift/ to ./azul-swift and libazul next to the binary,
// then: swift build -Xlinker -L. && ./.build/debug/AzulStyles
import PackageDescription

let package = Package(
    name: "AzulStyles",
    dependencies: [
        .package(path: "azul-swift"),
    ],
    targets: [
        .executableTarget(
            name: "AzulStyles",
            dependencies: [.product(name: "Azul", package: "azul-swift")],
            path: "Sources/AzulStyles"
        ),
    ]
)
"#;
